/// Project a world point into the pane's window-px space (viewport-local + pane origin).
pub fn ovProject(cam: model_paint.Camera, p: [3]f32, ox: f32, oy: f32) ?[2]f32 {
    const s = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, p) orelse return null;
    return .{ s[0] + ox, s[1] + oy };
}
/// Force a scissor-SEGMENT boundary without changing the clip rect. Within one segment
/// the pipelines draw in a fixed order (…capsules, THEN polys), so a poly fill emitted
/// alongside capsules would land ON TOP of them. Breaking the segment puts everything
/// emitted after this call in a later segment — drawn after (above) everything before it.
pub fn overlayLayerBreak(ox: f32, oy: f32) void {
    core.popScissor();
    core.pushScissor(ox, oy, z3d.g_paint_vp_w, z3d.g_paint_vp_h);
}
/// Marquee box (any mode) — four thin capsules forming the rect outline (window px).
pub fn drawMarqueeOverlay() void {
    if (!z3d.g_mq_active) return;
    const x0 = z3d.g_mq[0];
    const y0 = z3d.g_mq[1];
    const x1 = z3d.g_mq[2];
    const y1 = z3d.g_mq[3];
    z3d.overlayLine(x0, y0, x1, y0, z3d.OV_MARQUEE[0], z3d.OV_MARQUEE[1], z3d.OV_MARQUEE[2], 2.0);
    z3d.overlayLine(x1, y0, x1, y1, z3d.OV_MARQUEE[0], z3d.OV_MARQUEE[1], z3d.OV_MARQUEE[2], 2.0);
    z3d.overlayLine(x1, y1, x0, y1, z3d.OV_MARQUEE[0], z3d.OV_MARQUEE[1], z3d.OV_MARQUEE[2], 2.0);
    z3d.overlayLine(x0, y1, x0, y0, z3d.OV_MARQUEE[0], z3d.OV_MARQUEE[1], z3d.OV_MARQUEE[2], 2.0);
}
/// One grid line on the stage floor: a world segment as a single dim capsule (a straight
/// world line projects to a straight screen line, so two endpoints are exact).
pub fn stageLine(cam: model_paint.Camera, a: [3]f32, b: [3]f32, col: [4]f32, w: f32, ox: f32, oy: f32) void {
    const pa = z3d.ovProject(cam, a, ox, oy) orelse return;
    const pb = z3d.ovProject(cam, b, ox, oy) orelse return;
    core.drawCapsule(pa[0], pa[1], pb[0], pb[1], col[0], col[1], col[2], col[3], w);
}
/// The 3×3 tile-panel fills on the ground plane — each panel is ONE game tile (1 m); the
/// center panel (the fine cell) is slightly brighter. Emitted as polys → must sit in its
/// own segment BELOW the stage lines.
pub fn drawStagePanels(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const half = z3d.STAGE_TILE_M * @as(f32, @floatFromInt(z3d.STAGE_TILES)) * 0.5;
    var iz: u32 = 0;
    while (iz < z3d.STAGE_TILES) : (iz += 1) {
        var ix: u32 = 0;
        while (ix < z3d.STAGE_TILES) : (ix += 1) {
            const x0 = -half + @as(f32, @floatFromInt(ix)) * z3d.STAGE_TILE_M;
            const z0 = -half + @as(f32, @floatFromInt(iz)) * z3d.STAGE_TILE_M;
            const c00 = z3d.ovProject(cam, .{ x0, 0, z0 }, ox, oy) orelse continue;
            const c10 = z3d.ovProject(cam, .{ x0 + z3d.STAGE_TILE_M, 0, z0 }, ox, oy) orelse continue;
            const c11 = z3d.ovProject(cam, .{ x0 + z3d.STAGE_TILE_M, 0, z0 + z3d.STAGE_TILE_M }, ox, oy) orelse continue;
            const c01 = z3d.ovProject(cam, .{ x0, 0, z0 + z3d.STAGE_TILE_M }, ox, oy) orelse continue;
            const center = ix == z3d.STAGE_TILES / 2 and iz == z3d.STAGE_TILES / 2;
            const col = if (center) z3d.STAGE_PANEL_CENTER else z3d.STAGE_PANEL;
            core.drawTri(c00[0], c00[1], c10[0], c10[1], c11[0], c11[1], col[0], col[1], col[2], col[3]);
            core.drawTri(c00[0], c00[1], c11[0], c11[1], c01[0], c01[1], col[0], col[1], col[2], col[3]);
        }
    }
}
/// Tile-boundary lines, the center panel's 16×16 fine sub-grid (1 u pitch), and the world
/// axis lines from origin (X red, Y green, Z blue — the axisColor convention).
pub fn drawStageLines(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const half = z3d.STAGE_TILE_M * @as(f32, @floatFromInt(z3d.STAGE_TILES)) * 0.5;
    var i: u32 = 0;
    while (i <= z3d.STAGE_TILES) : (i += 1) {
        const t = -half + @as(f32, @floatFromInt(i)) * z3d.STAGE_TILE_M;
        z3d.stageLine(cam, .{ t, 0, -half }, .{ t, 0, half }, z3d.STAGE_LINE, 1.4, ox, oy);
        z3d.stageLine(cam, .{ -half, 0, t }, .{ half, 0, t }, z3d.STAGE_LINE, 1.4, ox, oy);
    }
    const ch = z3d.STAGE_TILE_M * 0.5; // center panel spans [-ch, ch]
    const pitch = z3d.STAGE_TILE_M / @as(f32, @floatFromInt(z3d.STAGE_FINE_DIV));
    var k: u32 = 1;
    while (k < z3d.STAGE_FINE_DIV) : (k += 1) { // interior lines; the borders ARE tile lines
        const t = -ch + @as(f32, @floatFromInt(k)) * pitch;
        z3d.stageLine(cam, .{ t, 0, -ch }, .{ t, 0, ch }, z3d.STAGE_FINE_LINE, 1.0, ox, oy);
        z3d.stageLine(cam, .{ -ch, 0, t }, .{ ch, 0, t }, z3d.STAGE_FINE_LINE, 1.0, ox, oy);
    }
    var a: i32 = 0;
    while (a < 3) : (a += 1) {
        const c = z3d.axisColor(a);
        z3d.stageLine(cam, .{ 0, 0, 0 }, z3d.vmul(z3d.axisVec(a), z3d.STAGE_AXIS_M), .{ c[0], c[1], c[2], z3d.STAGE_AXIS_ALPHA }, 1.8, ox, oy);
    }
}

pub fn stageScaleCameraRight(cam: model_paint.Camera) [3]f32 {
    const forward = z3d.vnorm(z3d.vsub(cam.target, cam.eye));
    const right = z3d.vcross(forward, .{ 0, 1, 0 });
    return if (z3d.vdot(right, right) < 1e-8) .{ 1, 0, 0 } else z3d.vnorm(right);
}

pub fn stageScalePoint(origin: [3]f32, right: [3]f32, lateral_m: f32, height_m: f32) [3]f32 {
    return .{ origin[0] + right[0] * lateral_m, height_m, origin[2] + right[2] * lateral_m };
}

pub fn stageScaleRulerOrigin(cam: model_paint.Camera, right: [3]f32) [3]f32 {
    const side_m = std.math.clamp(
        z3d.g_orbit.radius * z3d.STAGE_SCALE_CUE.ruler_side_radius_fraction,
        z3d.STAGE_SCALE_CUE.ruler_side_min_m,
        z3d.STAGE_SCALE_CUE.ruler_side_max_m,
    );
    return z3d.stageScalePoint(.{ cam.target[0], 0, cam.target[2] }, right, -side_m, 0);
}

pub fn stageScaleMannequinOrigin(ruler: [3]f32, right: [3]f32) [3]f32 {
    return z3d.stageScalePoint(ruler, right, -z3d.STAGE_SCALE_CUE.mannequin_ruler_gap_m, 0);
}

pub fn stageScaleMarkColor(tone: stage_scale.MarkTone) [4]f32 {
    return switch (tone) {
        .meter => z3d.STAGE_SCALE_CUE.meter,
        .collider => z3d.STAGE_SCALE_CUE.collider,
        .visual_head => z3d.STAGE_SCALE_CUE.visual_head,
    };
}

pub fn stageScaleTickEnd(ruler: [3]f32, right: [3]f32, height_m: f32, length_m: f32) [3]f32 {
    return z3d.stageScalePoint(ruler, right, length_m, height_m);
}

pub fn stageScalePointInViewport(p: [2]f32) bool {
    const margin = z3d.STAGE_SCALE_CUE.mannequin_viewport_margin_px;
    return p[0] >= z3d.g_paint_vp_x + margin and p[0] <= z3d.g_paint_vp_x + z3d.g_paint_vp_w - margin and
        p[1] >= z3d.g_paint_vp_y + margin and p[1] <= z3d.g_paint_vp_y + z3d.g_paint_vp_h - margin;
}

/// A lightweight standing player reference. It is deliberately an overlay—not a scene
/// mesh—so it can never be selected, baked, painted, or confused with the authored model.
pub fn drawStageScaleMannequin(cam: model_paint.Camera, origin: [3]f32, right: [3]f32, ox: f32, oy: f32) void {
    const col = z3d.STAGE_SCALE_CUE.mannequin;
    const feet = z3d.ovProject(cam, origin, ox, oy) orelse return;
    const visual_head_top = z3d.ovProject(cam, z3d.stageScalePoint(origin, right, 0, stage_scale.Tuning.player_visual_head_top_meters), ox, oy) orelse return;
    // A player taller than the current zoom should not leave a broken half-figure
    // on the edge of the stage. The ruler still shows every in-frame meter mark;
    // zoom out a notch and the full physical reference appears.
    if (!z3d.stageScalePointInViewport(feet) or !z3d.stageScalePointInViewport(visual_head_top)) return;
    const shoulder = z3d.stageScalePoint(origin, right, 0, z3d.STAGE_SCALE_CUE.mannequin_shoulder_height_m);
    const hip = z3d.stageScalePoint(origin, right, 0, z3d.STAGE_SCALE_CUE.mannequin_hip_height_m);
    const head_center = z3d.stageScalePoint(origin, right, 0, stage_scale.Tuning.player_visual_head_top_meters - z3d.STAGE_SCALE_CUE.mannequin_head_radius_m);
    const head_base = z3d.stageScalePoint(origin, right, 0, stage_scale.Tuning.player_visual_head_top_meters - z3d.STAGE_SCALE_CUE.mannequin_head_radius_m * 2);
    const left_shoulder = z3d.stageScalePoint(origin, right, -z3d.STAGE_SCALE_CUE.mannequin_shoulder_half_width_m, shoulder[1]);
    const right_shoulder = z3d.stageScalePoint(origin, right, z3d.STAGE_SCALE_CUE.mannequin_shoulder_half_width_m, shoulder[1]);
    const left_hand = z3d.stageScalePoint(origin, right, -z3d.STAGE_SCALE_CUE.mannequin_hand_half_width_m, z3d.STAGE_SCALE_CUE.mannequin_hand_height_m);
    const right_hand = z3d.stageScalePoint(origin, right, z3d.STAGE_SCALE_CUE.mannequin_hand_half_width_m, z3d.STAGE_SCALE_CUE.mannequin_hand_height_m);
    const left_foot = z3d.stageScalePoint(origin, right, -z3d.STAGE_SCALE_CUE.mannequin_foot_half_width_m, 0);
    const right_foot = z3d.stageScalePoint(origin, right, z3d.STAGE_SCALE_CUE.mannequin_foot_half_width_m, 0);

    z3d.stageLine(cam, hip, shoulder, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, shoulder, head_base, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, left_shoulder, right_shoulder, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, left_shoulder, left_hand, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, right_shoulder, right_hand, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, hip, left_foot, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);
    z3d.stageLine(cam, hip, right_foot, col, z3d.STAGE_SCALE_CUE.mannequin_line_width_px, ox, oy);

    const head = z3d.ovProject(cam, head_center, ox, oy) orelse return;
    const units_per_px = @max(@as(f32, 0.0001), z3d.worldUnitsPerPixel(cam, head_center));
    const raw_head_diameter_px = z3d.STAGE_SCALE_CUE.mannequin_head_radius_m * 2 / units_per_px;
    const head_diameter_px = @max(
        z3d.STAGE_SCALE_CUE.mannequin_head_min_diameter_px,
        @min(z3d.STAGE_SCALE_CUE.mannequin_head_max_diameter_px, raw_head_diameter_px),
    );
    core.drawCapsule(head[0], head[1], head[0], head[1], z3d.OV_HALO[0], z3d.OV_HALO[1], z3d.OV_HALO[2], z3d.OV_HALO[3], head_diameter_px + 3.5);
    core.drawCapsule(head[0], head[1], head[0], head[1], col[0], col[1], col[2], col[3], head_diameter_px);
}

/// Height cues beside the existing 1m floor grid: a 0–3m ruler, distinct collider and
/// visual-head guides, and a passive mannequin whose feet sit on the same y=0 plane.
pub fn drawStageScaleCue(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const right = z3d.stageScaleCameraRight(cam);
    const ruler = z3d.stageScaleRulerOrigin(cam, right);
    const mannequin = z3d.stageScaleMannequinOrigin(ruler, right);
    const ruler_top = [3]f32{ ruler[0], stage_scale.Tuning.ruler_height_meters, ruler[2] };
    z3d.stageLine(cam, ruler, ruler_top, z3d.STAGE_SCALE_CUE.ruler, z3d.STAGE_SCALE_CUE.ruler_width_px, ox, oy);

    var tick_index: u32 = 0;
    while (tick_index <= stage_scale.minorTickCount()) : (tick_index += 1) {
        const height_m = stage_scale.tickMeters(tick_index);
        const major = stage_scale.isMajorTick(tick_index);
        const tick_length_m = if (major) z3d.STAGE_SCALE_CUE.ruler_major_tick_length_m else z3d.STAGE_SCALE_CUE.ruler_minor_tick_length_m;
        const tick_col = if (major) z3d.STAGE_SCALE_CUE.meter else z3d.STAGE_SCALE_CUE.ruler;
        z3d.stageLine(cam, .{ ruler[0], height_m, ruler[2] }, z3d.stageScaleTickEnd(ruler, right, height_m, tick_length_m), tick_col, z3d.STAGE_SCALE_CUE.tick_width_px, ox, oy);
    }

    for (stage_scale.reference_marks) |mark| {
        const col = z3d.stageScaleMarkColor(mark.tone);
        const tick_end = z3d.stageScaleTickEnd(ruler, right, mark.meters, z3d.STAGE_SCALE_CUE.ruler_reference_tick_length_m);
        const guide_start = z3d.stageScalePoint(mannequin, right, z3d.STAGE_SCALE_CUE.mannequin_shoulder_half_width_m, mark.meters);
        const guide_col = [4]f32{ col[0], col[1], col[2], z3d.STAGE_SCALE_CUE.guide_alpha };
        z3d.stageLine(cam, .{ ruler[0], mark.meters, ruler[2] }, tick_end, col, z3d.STAGE_SCALE_CUE.reference_width_px, ox, oy);
        z3d.stageLine(cam, guide_start, .{ ruler[0], mark.meters, ruler[2] }, guide_col, z3d.STAGE_SCALE_CUE.guide_width_px, ox, oy);
    }
    z3d.drawStageScaleMannequin(cam, mannequin, right, ox, oy);
}

pub fn drawStageScaleLabel(label: []const u8, x: f32, y: f32, col: [4]f32) void {
    core.drawTextLine(label, x + 1, y + 1, z3d.STAGE_SCALE_CUE.label_font_px, z3d.STAGE_SCALE_CUE.text_shadow[0], z3d.STAGE_SCALE_CUE.text_shadow[1], z3d.STAGE_SCALE_CUE.text_shadow[2], z3d.STAGE_SCALE_CUE.text_shadow[3]);
    core.drawTextLine(label, x, y, z3d.STAGE_SCALE_CUE.label_font_px, col[0], col[1], col[2], col[3]);
}

/// Text rides a later overlay segment than the ruler capsules, keeping labels readable on
/// either dark stage space or a bright model face.
pub fn drawStageScaleText(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const right = z3d.stageScaleCameraRight(cam);
    const ruler = z3d.stageScaleRulerOrigin(cam, right);
    const title = z3d.ovProject(cam, .{ ruler[0], stage_scale.Tuning.ruler_height_meters, ruler[2] }, ox, oy);
    if (title) |p| z3d.drawStageScaleLabel("PLAYER SCALE", p[0] + z3d.STAGE_SCALE_CUE.label_pad_px, p[1] - z3d.STAGE_SCALE_CUE.label_top_rise_px, z3d.STAGE_SCALE_CUE.meter);
    for (stage_scale.reference_marks) |mark| {
        const tick_end = z3d.stageScaleTickEnd(ruler, right, mark.meters, z3d.STAGE_SCALE_CUE.ruler_reference_tick_length_m);
        const p = z3d.ovProject(cam, tick_end, ox, oy) orelse continue;
        const col = z3d.stageScaleMarkColor(mark.tone);
        z3d.drawStageScaleLabel(mark.label, p[0] + z3d.STAGE_SCALE_CUE.label_pad_px, p[1] - z3d.STAGE_SCALE_CUE.label_center_rise_px, col);
    }
}

pub fn stageMeasurementMidpoint(a: [3]f32, b: [3]f32) [3]f32 {
    return .{ (a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5, (a[2] + b[2]) * 0.5 };
}

pub fn drawStageMeasurementBox(cam: model_paint.Camera, min: [3]f32, max: [3]f32, ox: f32, oy: f32) void {
    const corners = [8][3]f32{
        .{ min[0], min[1], min[2] }, .{ max[0], min[1], min[2] },
        .{ min[0], max[1], min[2] }, .{ max[0], max[1], min[2] },
        .{ min[0], min[1], max[2] }, .{ max[0], min[1], max[2] },
        .{ min[0], max[1], max[2] }, .{ max[0], max[1], max[2] },
    };
    const edges = [12][2]u8{
        .{ 0, 1 }, .{ 2, 3 }, .{ 4, 5 }, .{ 6, 7 },
        .{ 0, 2 }, .{ 1, 3 }, .{ 4, 6 }, .{ 5, 7 },
        .{ 0, 4 }, .{ 1, 5 }, .{ 2, 6 }, .{ 3, 7 },
    };
    for (edges) |edge| {
        z3d.stageLine(cam, corners[edge[0]], corners[edge[1]], z3d.STAGE_MEASUREMENT_CUE.bounds, z3d.STAGE_MEASUREMENT_CUE.bounds_width_px, ox, oy);
    }
}

pub fn drawStageMeasurementTick(cam: model_paint.Camera, point: [3]f32, axis: usize, half_tick_m: f32, color: [4]f32, ox: f32, oy: f32) void {
    var a = point;
    var b = point;
    const cross_axis: usize = if (axis == 1) 0 else 1;
    a[cross_axis] -= half_tick_m;
    b[cross_axis] += half_tick_m;
    z3d.stageLine(cam, a, b, color, z3d.STAGE_MEASUREMENT_CUE.leader_width_px, ox, oy);
}

/// Draw model/part/selection bounds and three world-axis dimension leaders. The welded
/// topology owns the measured subject; this layer only projects that answer, so render
/// geometry and measurement geometry cannot become competing sources of truth.
pub fn drawStageMeasurements(cam: model_paint.Camera, ox: f32, oy: f32) void {
    z3d.g_stage_measurement_frame = null;
    const bounds = mesh_edit.measurementBoundsPub() orelse return;
    const size = bounds.size();
    const largest = @max(size[0], @max(size[1], size[2]));
    const offset_m = std.math.clamp(
        largest * z3d.STAGE_MEASUREMENT_CUE.leader_offset_fraction,
        z3d.STAGE_MEASUREMENT_CUE.leader_offset_min_m,
        z3d.STAGE_MEASUREMENT_CUE.leader_offset_max_m,
    );
    const half_tick_m = std.math.clamp(
        offset_m * z3d.STAGE_MEASUREMENT_CUE.endpoint_tick_fraction,
        z3d.STAGE_MEASUREMENT_CUE.endpoint_tick_min_m,
        z3d.STAGE_MEASUREMENT_CUE.endpoint_tick_max_m,
    );
    z3d.drawStageMeasurementBox(cam, bounds.min, bounds.max, ox, oy);

    // X (width) sits below the near-low edge.
    const x_start = [3]f32{ bounds.min[0], bounds.min[1] - offset_m, bounds.min[2] };
    const x_end = [3]f32{ bounds.max[0], bounds.min[1] - offset_m, bounds.min[2] };
    z3d.stageLine(cam, .{ bounds.min[0], bounds.min[1], bounds.min[2] }, x_start, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, .{ bounds.max[0], bounds.min[1], bounds.min[2] }, x_end, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, x_start, x_end, z3d.STAGE_MEASUREMENT_CUE.axis_x, z3d.STAGE_MEASUREMENT_CUE.leader_width_px, ox, oy);
    z3d.drawStageMeasurementTick(cam, x_start, 0, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_x, ox, oy);
    z3d.drawStageMeasurementTick(cam, x_end, 0, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_x, ox, oy);

    // Y (height) sits outside the near-right edge.
    const y_start = [3]f32{ bounds.max[0] + offset_m, bounds.min[1], bounds.min[2] };
    const y_end = [3]f32{ bounds.max[0] + offset_m, bounds.max[1], bounds.min[2] };
    z3d.stageLine(cam, .{ bounds.max[0], bounds.min[1], bounds.min[2] }, y_start, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, .{ bounds.max[0], bounds.max[1], bounds.min[2] }, y_end, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, y_start, y_end, z3d.STAGE_MEASUREMENT_CUE.axis_y, z3d.STAGE_MEASUREMENT_CUE.leader_width_px, ox, oy);
    z3d.drawStageMeasurementTick(cam, y_start, 1, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_y, ox, oy);
    z3d.drawStageMeasurementTick(cam, y_end, 1, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_y, ox, oy);

    // Z (depth) sits below and just outside the left edge, clear of the X label.
    const z_start = [3]f32{ bounds.min[0] - offset_m, bounds.min[1] - offset_m, bounds.min[2] };
    const z_end = [3]f32{ bounds.min[0] - offset_m, bounds.min[1] - offset_m, bounds.max[2] };
    z3d.stageLine(cam, .{ bounds.min[0], bounds.min[1], bounds.min[2] }, z_start, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, .{ bounds.min[0], bounds.min[1], bounds.max[2] }, z_end, z3d.STAGE_MEASUREMENT_CUE.extension, z3d.STAGE_MEASUREMENT_CUE.extension_width_px, ox, oy);
    z3d.stageLine(cam, z_start, z_end, z3d.STAGE_MEASUREMENT_CUE.axis_z, z3d.STAGE_MEASUREMENT_CUE.leader_width_px, ox, oy);
    z3d.drawStageMeasurementTick(cam, z_start, 2, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_z, ox, oy);
    z3d.drawStageMeasurementTick(cam, z_end, 2, half_tick_m, z3d.STAGE_MEASUREMENT_CUE.axis_z, ox, oy);

    z3d.g_stage_measurement_frame = .{
        .bounds = bounds,
        .axis_label_points = .{
            z3d.stageMeasurementMidpoint(x_start, x_end),
            z3d.stageMeasurementMidpoint(y_start, y_end),
            z3d.stageMeasurementMidpoint(z_start, z_end),
        },
        .title_point = .{ bounds.max[0], bounds.max[1] + offset_m, bounds.max[2] },
    };
}

pub fn stageMeasurementSubjectLabel(subject: mesh_edit.MeasurementSubject) []const u8 {
    return switch (subject) {
        .selection => "SELECTION SIZE",
        .scope => "FOCUSED PART SIZE",
        .model => "MODEL SIZE",
    };
}

pub fn drawStageMeasurementLabel(label: []const u8, x: f32, y: f32, color: [4]f32) void {
    const shadow = z3d.STAGE_MEASUREMENT_CUE.text_shadow;
    core.drawTextLine(label, x + 1, y + 1, z3d.STAGE_MEASUREMENT_CUE.label_font_px, shadow[0], shadow[1], shadow[2], shadow[3]);
    core.drawTextLine(label, x, y, z3d.STAGE_MEASUREMENT_CUE.label_font_px, color[0], color[1], color[2], color[3]);
}

pub fn drawStageMeasurementText(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const frame = z3d.g_stage_measurement_frame orelse return;
    const size = frame.bounds.size();
    const colors = [3][4]f32{ z3d.STAGE_MEASUREMENT_CUE.axis_x, z3d.STAGE_MEASUREMENT_CUE.axis_y, z3d.STAGE_MEASUREMENT_CUE.axis_z };
    const axis_names = [3]u8{ 'X', 'Y', 'Z' };
    var axis: usize = 0;
    while (axis < 3) : (axis += 1) {
        const projected = z3d.ovProject(cam, frame.axis_label_points[axis], ox, oy) orelse continue;
        var buffer: [64]u8 = undefined;
        const label = std.fmt.bufPrint(&buffer, "{c}  {d:.3} m  ·  {d:.2} u", .{
            axis_names[axis],
            size[axis],
            stage_scale.metersToUnits(size[axis]),
        }) catch continue;
        z3d.drawStageMeasurementLabel(
            label,
            projected[0] + z3d.STAGE_MEASUREMENT_CUE.label_pad_px,
            projected[1] - z3d.STAGE_MEASUREMENT_CUE.label_rise_px,
            colors[axis],
        );
    }
    const title = z3d.ovProject(cam, frame.title_point, ox, oy) orelse return;
    z3d.drawStageMeasurementLabel(
        z3d.stageMeasurementSubjectLabel(frame.bounds.subject),
        title[0] + z3d.STAGE_MEASUREMENT_CUE.label_pad_px,
        title[1] - z3d.STAGE_MEASUREMENT_CUE.title_rise_px,
        z3d.STAGE_MEASUREMENT_CUE.title,
    );
}
/// Faces the current selection touches (any mode) — alloc'd, caller frees. Null when
/// nothing is selected (or allocation fails), so callers can skip the lookup entirely.
pub fn selectionFaceMaskAlloc(fc: u32) ?[]bool {
    if (fc == 0) return null;
    const mask = std.heap.c_allocator.alloc(bool, fc) catch return null;
    if (mesh_edit.buildDeleteMask(mask) == 0) {
        std.heap.c_allocator.free(mask);
        return null;
    }
    return mask;
}

pub fn drawFaceSemanticDot(x: f32, y: f32, selected: bool, glass: bool) void {
    if (glass) {
        // Selection already owns the face wash (orange); retain cyan at the centroid so
        // choosing a glass face never hides the very property the user is inspecting.
        const radius = if (selected) z3d.OV_FACE_DOT_GLASS_SEL_PX else z3d.OV_FACE_DOT_GLASS_PX;
        z3d.overlayDot(x, y, z3d.OV_FACE_DOT_GLASS[0], z3d.OV_FACE_DOT_GLASS[1], z3d.OV_FACE_DOT_GLASS[2], radius);
    } else if (selected) {
        z3d.overlayDot(x, y, z3d.OV_ORANGE[0], z3d.OV_ORANGE[1], z3d.OV_ORANGE[2], z3d.OV_FACE_DOT_SEL_PX);
    } else {
        z3d.overlayDot(x, y, z3d.OV_FACE_DOT[0], z3d.OV_FACE_DOT[1], z3d.OV_FACE_DOT[2], z3d.OV_FACE_DOT_PX);
    }
}
/// Face-mode wash (req_2618 gap B): every FRONT-facing in-scope triangle gets a subtle
/// translucent overlay quad (selected faces orange, authored glass cyan). Pure overlay
/// polys — the paint atlas and vertex colors are never touched, so nothing can bake.
pub fn drawFaceTintOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const pos = model_paint.positions() orelse return;
    const fc = model_paint.faceCount();
    if (fc == 0 or fc > z3d.OV_MAX_FACE_TINT) return;
    const mask = z3d.selectionFaceMaskAlloc(fc);
    defer if (mask) |m| std.heap.c_allocator.free(m);
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        if (!mesh_edit.faceInScopePub(f)) continue;
        const b = @as(usize, f) * 9;
        if (b + 8 >= pos.len) break;
        const p0: [3]f32 = .{ pos[b + 0], pos[b + 1], pos[b + 2] };
        const p1: [3]f32 = .{ pos[b + 3], pos[b + 4], pos[b + 5] };
        const p2: [3]f32 = .{ pos[b + 6], pos[b + 7], pos[b + 8] };
        const n = z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0));
        const cen = z3d.vmul(z3d.vadd(z3d.vadd(p0, p1), p2), 1.0 / 3.0);
        if (!mesh_edit.xray()) {
            if (z3d.vdot(n, z3d.vsub(cam.eye, cen)) <= 0) continue; // back-facing in Surface mode
            if (mesh_edit.overlayPointOccludedPub(cen)) continue; // behind a nearer surface (req_3856)
        }
        const a = z3d.ovProject(cam, p0, ox, oy) orelse continue;
        const bb = z3d.ovProject(cam, p1, ox, oy) orelse continue;
        const cc = z3d.ovProject(cam, p2, ox, oy) orelse continue;
        const selected = if (mask) |m| m[f] else false;
        const col = if (selected) z3d.OV_FACE_TINT_SEL else if (model_paint.faceIsGlass(f)) z3d.OV_FACE_TINT_GLASS else z3d.OV_FACE_TINT;
        core.drawTri(a[0], a[1], bb[0], bb[1], cc[0], cc[1], col[0], col[1], col[2], col[3]);
    }
}

/// Whole-model band map. This intentionally replaces the ordinary blue/orange face
/// wash while active so selecting every face cannot hide the plan under one colour.
pub fn drawRetopoBandOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const planned = if (z3d.g_retopo_band_plan) |*value| value.faces else null;
    const manual = z3d.g_retopo_manual_bands;
    if (planned == null and manual == null) return;
    const pos = model_paint.positions() orelse return;
    const fc = model_paint.faceCount();
    const labels = planned orelse manual.?;
    if (fc == 0 or fc > z3d.OV_MAX_FACE_TINT or labels.len != fc) return;
    var face: u32 = 0;
    while (face < fc) : (face += 1) {
        // A retopology map is explicitly a WHOLE-resident-mesh review surface.
        // Active Outliner scope still gates edits, but must not hide planned faces.
        const base = @as(usize, face) * 9;
        if (base + 8 >= pos.len) break;
        const p0: [3]f32 = .{ pos[base], pos[base + 1], pos[base + 2] };
        const p1: [3]f32 = .{ pos[base + 3], pos[base + 4], pos[base + 5] };
        const p2: [3]f32 = .{ pos[base + 6], pos[base + 7], pos[base + 8] };
        const normal = z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0));
        const centroid = z3d.vmul(z3d.vadd(z3d.vadd(p0, p1), p2), 1.0 / 3.0);
        if (!mesh_edit.xray() and z3d.vdot(normal, z3d.vsub(cam.eye, centroid)) <= 0) continue;
        const a = z3d.ovProject(cam, p0, ox, oy) orelse continue;
        const b = z3d.ovProject(cam, p1, ox, oy) orelse continue;
        const c = z3d.ovProject(cam, p2, ox, oy) orelse continue;
        const label = labels[face];
        if (label != mesh_edit.RETOPO_BAND_UNASSIGNED) {
            const color = z3d.retopoBandColor(label);
            core.drawTri(a[0], a[1], b[0], b[1], c[0], c[1], color[0], color[1], color[2], z3d.RETOPO_BAND_TINT_ALPHA);
        } else {
            const selected = mesh_edit.faceSelectedPub(face);
            const col = if (selected) z3d.OV_FACE_TINT_SEL else if (model_paint.faceIsGlass(face)) z3d.OV_FACE_TINT_GLASS else z3d.OV_FACE_TINT;
            core.drawTri(a[0], a[1], b[0], b[1], c[0], c[1], col[0], col[1], col[2], col[3]);
        }
    }
}

/// Frozen before-image of the imported soup. It is projected in screen space over
/// the live mesh, so coincident areas reinforce while silhouette/curvature drift
/// visibly separates from the replacement surface. Only explicitly mapped source
/// faces draw; unfinished teaching coverage stays honest instead of becoming gray.
pub fn drawRetopoSourceGhost(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const ghost = if (z3d.g_retopo_source_ghost) |*value| value else return;
    if (!ghost.visible or ghost.bands.len == 0 or ghost.bands.len > z3d.OV_MAX_FACE_TINT or ghost.positions.len < ghost.bands.len * 9) return;
    for (ghost.bands, 0..) |label, face| {
        if (label == mesh_edit.RETOPO_BAND_UNASSIGNED) continue;
        const base = face * 9;
        const p0: [3]f32 = .{ ghost.positions[base], ghost.positions[base + 1], ghost.positions[base + 2] };
        const p1: [3]f32 = .{ ghost.positions[base + 3], ghost.positions[base + 4], ghost.positions[base + 5] };
        const p2: [3]f32 = .{ ghost.positions[base + 6], ghost.positions[base + 7], ghost.positions[base + 8] };
        const normal = z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0));
        const centroid = z3d.vmul(z3d.vadd(z3d.vadd(p0, p1), p2), 1.0 / 3.0);
        if (!mesh_edit.xray() and z3d.vdot(normal, z3d.vsub(cam.eye, centroid)) <= 0) continue;
        const a = z3d.ovProject(cam, p0, ox, oy) orelse continue;
        const b = z3d.ovProject(cam, p1, ox, oy) orelse continue;
        const c = z3d.ovProject(cam, p2, ox, oy) orelse continue;
        const color = z3d.retopoBandColor(label);
        core.drawTri(a[0], a[1], b[0], b[1], c[0], c[1], color[0], color[1], color[2], z3d.RETOPO_GHOST_TINT_ALPHA);
    }
}
pub const FaceDotAcc = struct { cen: [3]f32, nrm: [3]f32, w: f32, sel: bool, glass: bool };
/// Face-mode centroid dots — the old studio's signature look: one small dot per AUTHORED
/// face (a cube face reads as one dot, not two triangle dots), front-facing only.
pub fn drawFaceDotsOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const pos = model_paint.positions() orelse return;
    const fc = model_paint.faceCount();
    if (fc == 0 or fc > z3d.OV_MAX_FACE_TINT) return;
    const mask = z3d.selectionFaceMaskAlloc(fc);
    defer if (mask) |m| std.heap.c_allocator.free(m);
    var groups = std.AutoHashMapUnmanaged(u32, z3d.FaceDotAcc){};
    defer groups.deinit(std.heap.c_allocator);
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        if (!mesh_edit.faceInScopePub(f)) continue;
        const b = @as(usize, f) * 9;
        if (b + 8 >= pos.len) break;
        const p0: [3]f32 = .{ pos[b + 0], pos[b + 1], pos[b + 2] };
        const p1: [3]f32 = .{ pos[b + 3], pos[b + 4], pos[b + 5] };
        const p2: [3]f32 = .{ pos[b + 6], pos[b + 7], pos[b + 8] };
        const n = z3d.vcross(z3d.vsub(p1, p0), z3d.vsub(p2, p0));
        const cen = z3d.vmul(z3d.vadd(z3d.vadd(p0, p1), p2), 1.0 / 3.0);
        const selected = if (mask) |m| m[f] else false;
        const glass = model_paint.faceIsGlass(f);
        const grp = model_source.faceGroupOf(f);
        if (grp == model_source.NO_FACE_GROUP) {
            // Ungrouped soup: a dot per front-facing, unoccluded triangle.
            if (!mesh_edit.xray()) {
                if (z3d.vdot(n, z3d.vsub(cam.eye, cen)) <= 0) continue;
                if (mesh_edit.overlayPointOccludedPub(cen)) continue; // req_3856
            }
            const sp = z3d.ovProject(cam, cen, ox, oy) orelse continue;
            z3d.drawFaceSemanticDot(sp[0], sp[1], selected, glass);
            continue;
        }
        // Authored face: accumulate an area-weighted centroid across the group's tris.
        const w = @sqrt(z3d.vdot(n, n)); // 2 × tri area
        const g = groups.getOrPut(std.heap.c_allocator, grp) catch continue;
        if (!g.found_existing) g.value_ptr.* = .{ .cen = .{ 0, 0, 0 }, .nrm = .{ 0, 0, 0 }, .w = 0, .sel = false, .glass = false };
        g.value_ptr.cen = z3d.vadd(g.value_ptr.cen, z3d.vmul(cen, w));
        g.value_ptr.nrm = z3d.vadd(g.value_ptr.nrm, n);
        g.value_ptr.w += w;
        g.value_ptr.sel = g.value_ptr.sel or selected;
        g.value_ptr.glass = g.value_ptr.glass or glass;
    }
    var it = groups.iterator();
    while (it.next()) |entry| {
        const acc = entry.value_ptr.*;
        if (acc.w <= 1e-12) continue;
        const cen = z3d.vmul(acc.cen, 1.0 / acc.w);
        if (!mesh_edit.xray()) {
            if (z3d.vdot(acc.nrm, z3d.vsub(cam.eye, cen)) <= 0) continue; // back-facing in Surface mode
            if (mesh_edit.overlayPointOccludedPub(cen)) continue; // behind a nearer surface (req_3856)
        }
        const sp = z3d.ovProject(cam, cen, ox, oy) orelse continue;
        z3d.drawFaceSemanticDot(sp[0], sp[1], acc.sel, acc.glass);
    }
}
pub fn faceCornerIdentityColor(vertex: u32) [3]f32 {
    const hue_degrees = (vertex *% z3d.OV_FACE_CORNER_HUE_STEP_DEGREES) % 360;
    const sector = hue_degrees / 60;
    const remainder = hue_degrees % 60;
    const rising = z3d.OV_FACE_CORNER_CHROMA_BYTE * remainder / 60;
    const falling = z3d.OV_FACE_CORNER_CHROMA_BYTE * (60 - remainder) / 60;
    const x = if (sector % 2 == 0) rising else falling;
    const m = z3d.OV_FACE_CORNER_VALUE_BYTE - z3d.OV_FACE_CORNER_CHROMA_BYTE;
    const rgb = switch (sector) {
        0 => [3]u32{ z3d.OV_FACE_CORNER_CHROMA_BYTE, x, 0 },
        1 => [3]u32{ x, z3d.OV_FACE_CORNER_CHROMA_BYTE, 0 },
        2 => [3]u32{ 0, z3d.OV_FACE_CORNER_CHROMA_BYTE, x },
        3 => [3]u32{ 0, x, z3d.OV_FACE_CORNER_CHROMA_BYTE },
        4 => [3]u32{ x, 0, z3d.OV_FACE_CORNER_CHROMA_BYTE },
        else => [3]u32{ z3d.OV_FACE_CORNER_CHROMA_BYTE, 0, x },
    };
    const byte_to_unit = 1.0 / @as(f32, @floatFromInt(z3d.OV_FACE_CORNER_VALUE_BYTE));
    return .{
        @as(f32, @floatFromInt(rgb[0] + m)) * byte_to_unit,
        @as(f32, @floatFromInt(rgb[1] + m)) * byte_to_unit,
        @as(f32, @floatFromInt(rgb[2] + m)) * byte_to_unit,
    };
}
/// Selected face corners use their welded vertex id as a shared 2D/3D color key.
/// This is overlay-only authoring chrome; neither mesh colors nor atlas pixels change.
pub fn drawFaceCornerIdentityOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const face_count = model_paint.faceCount();
    var selected_count: u32 = 0;
    var face: u32 = 0;
    while (face < face_count) : (face += 1) {
        if (!mesh_edit.faceSelectedPub(face)) continue;
        selected_count += 1;
        if (selected_count > z3d.OV_MAX_FACE_CORNER_ID_TRIS) return;
    }
    if (selected_count == 0) return;
    face = 0;
    while (face < face_count) : (face += 1) {
        if (!mesh_edit.faceSelectedPub(face)) continue;
        const vertices = mesh_edit.faceCornerVerticesPub(face) orelse continue;
        for (vertices) |vertex| {
            const point = z3d.ovProject(cam, mesh_edit.vertPosPub(vertex), ox, oy) orelse continue;
            const color = z3d.faceCornerIdentityColor(vertex);
            z3d.overlayDot(point[0], point[1], color[0], color[1], color[2], z3d.OV_FACE_CORNER_ID_PX);
        }
    }
}
/// Naked Pen Edges wires in plain VIEW mode: a wire edge has no rasterizing face, so
/// without this pass a committed wire part is invisible the moment the user leaves the
/// vertex/edge/face tools. Edit modes render the same edges through drawEdgeOverlay.
pub fn drawWireEdgesOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    if (mesh_edit.boundaryEdgeCount() > z3d.OV_MAX_EDGE_LINES) return;
    const n = mesh_edit.edgeCount();
    var e: u32 = 0;
    while (e < n) : (e += 1) {
        if (!mesh_edit.edgeIsWirePub(e)) continue;
        const ep = mesh_edit.edgeEndpointsPub(e);
        const a = z3d.ovProject(cam, mesh_edit.vertPosPub(ep[0]), ox, oy) orelse continue;
        const b = z3d.ovProject(cam, mesh_edit.vertPosPub(ep[1]), ox, oy) orelse continue;
        z3d.overlayLine(a[0], a[1], b[0], b[1], z3d.OV_WIRE[0], z3d.OV_WIRE[1], z3d.OV_WIRE[2], 1.6);
    }
}
/// The model's BOUNDARY edges as real lines (Blender/Blockbench style) — triangulation
/// diagonals stay hidden (req_2367). Vertex/edge modes draw them at full presence; face
/// mode gets a dimmer pass so authored faces read (and loop-cut previews show, req_2625).
/// While a loop-cut session is live, edges lying in a previewed cut plane accent bright.
pub fn drawEdgeOverlay(cam: model_paint.Camera, mode: u8, ox: f32, oy: f32) void {
    if (mesh_edit.boundaryEdgeCount() > z3d.OV_MAX_EDGE_LINES) return;
    var lc_dir: ?[3]f32 = null;
    var lc_eps: f32 = 1e-4;
    var lc_planes: []const f32 = &.{};
    if (z3d.g_lc) |*sp| {
        if (sp.last_plane_count > 0) {
            const d: usize = @min(sp.last_dir, 1);
            lc_dir = sp.dirs[d];
            lc_eps = @max(1e-4, (sp.hi[d] - sp.lo[d]) * 1e-3);
            lc_planes = sp.last_planes[0..sp.last_plane_count];
        }
    }
    const n = mesh_edit.edgeCount();
    var e: u32 = 0;
    while (e < n) : (e += 1) {
        if (!mesh_edit.edgeIsBoundaryPub(e)) continue;
        if (!mesh_edit.edgeInScopePub(e)) continue; // only the focused part's edges
        const selected = mode == 2 and mesh_edit.edgeSelectedPub(e);
        if (!selected and !mesh_edit.edgeCameraVisiblePub(e)) continue;
        const ep = mesh_edit.edgeEndpointsPub(e);
        const wa = mesh_edit.vertPosPub(ep[0]);
        const wb = mesh_edit.vertPosPub(ep[1]);
        const a = z3d.ovProject(cam, wa, ox, oy) orelse continue;
        const b = z3d.ovProject(cam, wb, ox, oy) orelse continue;
        // In edge mode a selected boundary edge draws bold-orange over the dim base.
        if (selected) {
            z3d.overlayLine(a[0], a[1], b[0], b[1], z3d.OV_ORANGE[0], z3d.OV_ORANGE[1], z3d.OV_ORANGE[2], 4.0);
            continue;
        }
        if (lc_dir) |ld| {
            const ca = z3d.vdot(wa, ld);
            const cb = z3d.vdot(wb, ld);
            if (@abs(ca - cb) <= lc_eps) {
                var on_plane = false;
                for (lc_planes) |pl| {
                    if (@abs(ca - pl) <= lc_eps) {
                        on_plane = true;
                        break;
                    }
                }
                if (on_plane) {
                    z3d.overlayLine(a[0], a[1], b[0], b[1], z3d.OV_LC_ACCENT[0], z3d.OV_LC_ACCENT[1], z3d.OV_LC_ACCENT[2], 3.0);
                    continue;
                }
            }
        }
        const w: f32 = if (mode == 3) 1.2 else 1.6;
        z3d.overlayLine(a[0], a[1], b[0], b[1], z3d.OV_EDGE[0], z3d.OV_EDGE[1], z3d.OV_EDGE[2], w);
    }
}
pub const LcHandleGeom = struct { p: [3]f32, a: [3]f32, b: [3]f32, axis: i32, half_w: f32 };
/// The loop-cut handle's world geometry — the ONE source drawn, hit-tested, and dragged
/// (the gizmoRingWorldR rule: draw and hit can never disagree). Anchor = the selection's
/// centroid moved onto the MIDDLE cut plane; when the comb is empty (offset scrubbed to
/// 0/1 pushed every plane out) it falls back to the span midpoint so a drag in flight
/// keeps a stable direction/scale.
pub fn lcHandleGeom(cam: model_paint.Camera) ?z3d.LcHandleGeom {
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return null;
    const d: usize = @min(sp.last_dir, 1);
    const dirv = sp.dirs[d];
    const target: f32 = if (sp.last_plane_count > 0)
        sp.last_planes[sp.last_plane_count / 2]
    else
        (sp.lo[d] + sp.hi[d]) * 0.5;
    // Slide the centroid along the cut direction onto the middle plane (dot-space).
    const p = z3d.vadd(sp.sel_center, z3d.vmul(dirv, target - z3d.vdot(sp.sel_center, dirv)));
    const half_w = z3d.worldUnitsPerPixel(cam, p) * z3d.OV_LC_HANDLE_PX;
    return .{
        .p = p,
        .a = z3d.vadd(p, z3d.vmul(dirv, -half_w)),
        .b = z3d.vadd(p, z3d.vmul(dirv, half_w)),
        .axis = z3d.domAxis(dirv), // gizmo color only — the geometry runs along dirv
        .half_w = half_w,
    };
}
/// While a loop-cut popup session is live: a translate-style handle on the MIDDLE cut
/// plane, anchored at the selection's centroid — the drag surface for the offset
/// (meshLcHandleHit/meshLcHandleDrag, req_2625 gap DD).
pub fn drawLoopCutOverlay(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return;
    if (sp.last_plane_count == 0) return;
    const g = z3d.lcHandleGeom(cam) orelse return;
    const pa = z3d.ovProject(cam, g.a, ox, oy) orelse return;
    const pb = z3d.ovProject(cam, g.b, ox, oy) orelse return;
    const c = z3d.axisColor(g.axis);
    z3d.overlayLine(pa[0], pa[1], pb[0], pb[1], c[0], c[1], c[2], 4.0);
    z3d.overlayDot(pa[0], pa[1], c[0], c[1], c[2], 6);
    z3d.overlayDot(pb[0], pb[1], c[0], c[1], c[2], 6);
    const pc = z3d.ovProject(cam, g.p, ox, oy) orelse return;
    z3d.overlayDot(pc[0], pc[1], z3d.OV_LC_ACCENT[0], z3d.OV_LC_ACCENT[1], z3d.OV_LC_ACCENT[2], 5);
}
/// Is (mx,my) — window px, like meshGizmoHit — on the drawn loop-cut handle? Same
/// geometry as drawLoopCutOverlay via lcHandleGeom, same GIZMO_HIT_PX threshold. O(1).
pub fn meshLcHandleHit(mx: f32, my: f32) bool {
    if (!z3d.g_me_capture or !model_paint.hasTarget()) return false;
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return false;
    if (sp.last_plane_count == 0) return false; // no comb drawn → nothing to grab
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const g = z3d.lcHandleGeom(cam) orelse return false;
    const pa = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, g.a) orelse return false;
    const pb = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, g.b) orelse return false;
    return z3d.segDist2(z3d.vpLocalX(mx), z3d.vpLocalY(my), pa[0], pa[1], pb[0], pb[1]) <= z3d.GIZMO_HIT_PX * z3d.GIZMO_HIT_PX;
}
/// Drag the grabbed loop-cut handle by a pixel delta: project the delta onto the
/// handle's SCREEN direction, map it through the drawn handle length to world units (the
/// meshGizmoDrag precision rule), convert to an offset-frac delta on the cut axis, clamp
/// 0..1, and re-preview at the session's own dir/cuts. Sign: lcPlanes' shift is
/// −(offset − size/2), i.e. dPlane/dOffset = −1, so offset moves OPPOSITE the world
/// delta — that is exactly what keeps the drawn comb following the cursor.
///
/// SNAP (req_2644 QQ): by default the offset lands on whole size-units — the mesh basis
/// (16 u to the tile, the studio gizmo's own law) — so a handle drag produces the same
/// clean authored offsets the popup steppers do. The cursor's RAW (continuous) offset
/// accumulates on the session so slow drags still cross the detent; `snap = false`
/// (Shift held in the engine's input loop) frees it to continuous.
pub fn meshLcHandleDrag(dx: f32, dy: f32, snap: bool) bool {
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return false;
    if (!model_paint.hasTarget()) return false;
    const d: usize = @min(sp.last_dir, 1);
    const span = sp.hi[d] - sp.lo[d];
    if (span < 1e-6) return false;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const g = z3d.lcHandleGeom(cam) orelse return false;
    const pa = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, g.a) orelse return false;
    const pb = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, g.b) orelse return false;
    const hdx = pb[0] - pa[0];
    const hdy = pb[1] - pa[1];
    const hlen = @sqrt(hdx * hdx + hdy * hdy);
    // Degenerate projection (axis into the screen): fall back to raw horizontal px at
    // the depth-based rate, mirroring meshGizmoDrag's fallback.
    var px = dx;
    var world_per_px = z3d.worldUnitsPerPixel(cam, g.p);
    if (hlen > 4) {
        px = (dx * hdx + dy * hdy) / hlen;
        world_per_px = (g.half_w * 2.0) / hlen;
    }
    const dir = sp.last_dir;
    const cuts = sp.last_cuts;
    const raw = std.math.clamp(sp.drag_raw_frac - (px * world_per_px) / span, 0.0, 1.0);
    var frac = raw;
    if (snap) {
        const step = z3d.LC_SNAP_WORLD / span; // one size-unit as an offset fraction
        if (step < 0.5) frac = std.math.clamp(@round(raw / step) * step, 0.0, 1.0);
    }
    const ok = z3d.meshLoopCutFacePreview(dir, cuts, frac);
    // The preview mirrored the SNAPPED frac into drag_raw_frac — restore the raw
    // accumulator so the next motion continues from the cursor, not the detent.
    if (z3d.g_lc) |*p2| p2.drag_raw_frac = raw;
    return ok;
}

// ── Orientation compass (req_2643 gap LL) ──────────────────────────────────────────
pub const CompassEnd = struct { x: f32, y: f32, depth: f32, axis: i32, positive: bool };
pub const CompassGeom = struct { cx: f32, cy: f32, ends: [6]z3d.CompassEnd };
/// Big enough pane to host the ball without crowding the corner chips.
pub fn compassVisible() bool {
    return z3d.g_paint_vp_w >= z3d.COMPASS_MIN_PANE_PX and z3d.g_paint_vp_h >= z3d.COMPASS_MIN_PANE_PX;
}
/// The ball's screen geometry from the CURRENT camera — rotation only: each world axis
/// is resolved against the view's right/up/forward basis (never the perspective
/// transform), so the ball reads pure orientation at a fixed corner size. depth > 0
/// means the end points AWAY from the viewer (into the screen).
pub fn compassGeom(cam: model_paint.Camera) z3d.CompassGeom {
    const cx = z3d.g_paint_vp_x + z3d.COMPASS_MARGIN_PX + z3d.COMPASS_R_PX;
    const cy = z3d.g_paint_vp_y + z3d.g_paint_vp_h - z3d.COMPASS_MARGIN_PX - z3d.COMPASS_R_PX;
    const fwd = z3d.vnorm(z3d.vsub(cam.target, cam.eye));
    var right = z3d.vcross(fwd, .{ 0, 1, 0 });
    right = if (z3d.vdot(right, right) < 1e-8) .{ 1, 0, 0 } else z3d.vnorm(right);
    const up = z3d.vcross(right, fwd);
    var g = z3d.CompassGeom{ .cx = cx, .cy = cy, .ends = undefined };
    var a: i32 = 0;
    while (a < 3) : (a += 1) {
        const e = z3d.axisVec(a);
        const sx = z3d.vdot(e, right) * z3d.COMPASS_ARM_PX;
        const sy = -z3d.vdot(e, up) * z3d.COMPASS_ARM_PX; // screen y grows downward
        const depth = z3d.vdot(e, fwd);
        g.ends[@intCast(a * 2)] = .{ .x = cx + sx, .y = cy + sy, .depth = depth, .axis = a, .positive = true };
        g.ends[@intCast(a * 2 + 1)] = .{ .x = cx - sx, .y = cy - sy, .depth = -depth, .axis = a, .positive = false };
    }
    return g;
}
/// The ball itself (capsule layer): backdrop disc + rim, then the six ends painter's-
/// ordered back-to-front so near dots cover far arms at the centre. Positive ends get
/// an arm line + solid dot (labels ride a LATER glyph segment — text flushes before
/// capsules inside one segment); negative ends a dimmer hollow ring.
pub fn drawCompassBall(cam: model_paint.Camera) void {
    const g = z3d.compassGeom(cam);
    core.drawCapsule(g.cx, g.cy, g.cx, g.cy, z3d.COMPASS_RIM[0], z3d.COMPASS_RIM[1], z3d.COMPASS_RIM[2], z3d.COMPASS_RIM[3], z3d.COMPASS_R_PX * 2 + 3);
    core.drawCapsule(g.cx, g.cy, g.cx, g.cy, z3d.COMPASS_BACK[0], z3d.COMPASS_BACK[1], z3d.COMPASS_BACK[2], z3d.COMPASS_BACK[3], z3d.COMPASS_R_PX * 2);
    var order: [6]usize = .{ 0, 1, 2, 3, 4, 5 };
    var i: usize = 0;
    while (i < 6) : (i += 1) { // 6 items: selection sort is the whole story
        var j: usize = i + 1;
        while (j < 6) : (j += 1) {
            if (g.ends[order[j]].depth > g.ends[order[i]].depth) {
                const t = order[i];
                order[i] = order[j];
                order[j] = t;
            }
        }
    }
    for (order) |k| {
        const e = g.ends[k];
        const c = z3d.axisColor(e.axis);
        const fade: f32 = if (e.depth > 0) z3d.COMPASS_AWAY_FADE else 1.0;
        if (e.positive) {
            core.drawCapsule(g.cx, g.cy, e.x, e.y, c[0] * fade, c[1] * fade, c[2] * fade, 1.0, 2.6);
            core.drawCapsule(e.x, e.y, e.x, e.y, c[0] * fade, c[1] * fade, c[2] * fade, 1.0, z3d.COMPASS_DOT_PX);
        } else {
            const dim = 0.55 * fade;
            core.drawCapsule(e.x, e.y, e.x, e.y, c[0] * dim, c[1] * dim, c[2] * dim, 0.95, z3d.COMPASS_DOT_NEG_PX);
            core.drawCapsule(e.x, e.y, e.x, e.y, z3d.COMPASS_BACK[0], z3d.COMPASS_BACK[1], z3d.COMPASS_BACK[2], 1.0, z3d.COMPASS_DOT_NEG_PX - z3d.COMPASS_RING_GAP_PX);
        }
    }
}
/// Axis labels on the positive dots + the live angle readout beside the ball. yaw/pitch
/// are derived from the SAME camera the frame drew (the exact orbitCamPos() angles:
/// yaw around +Y, pitch above the XZ plane), so the numbers stay honest even if a
/// future pane drives this camera without the orbit doors.
pub fn drawCompassText(cam: model_paint.Camera) void {
    const g = z3d.compassGeom(cam);
    const labels = [3][]const u8{ "X", "Y", "Z" };
    for (g.ends) |e| {
        if (!e.positive) continue;
        core.drawTextLine(labels[@intCast(e.axis)], e.x - 3, e.y - 6, 10, 0.04, 0.05, 0.09, 0.95);
    }
    const dir = z3d.vsub(cam.eye, cam.target);
    const len = @sqrt(z3d.vdot(dir, dir));
    if (len < 1e-6) return;
    const yaw_deg = std.math.atan2(dir[0], dir[2]) * 180.0 / std.math.pi;
    const pitch_deg = std.math.asin(std.math.clamp(dir[1] / len, -1.0, 1.0)) * 180.0 / std.math.pi;
    var buf: [64]u8 = undefined;
    const line = std.fmt.bufPrint(&buf, "yaw {d:.0}\u{00B0}  pitch {d:.0}\u{00B0}  fov {d:.0}\u{00B0}", .{ yaw_deg, pitch_deg, cam.fov_deg }) catch return;
    const tx = g.cx + z3d.COMPASS_R_PX + 10;
    const ty = g.cy - 8;
    core.drawTextLine(line, tx + 1, ty + 1, 12, 0.02, 0.03, 0.07, 0.85); // shadow
    core.drawTextLine(line, tx, ty, 12, z3d.COMPASS_TEXT[0], z3d.COMPASS_TEXT[1], z3d.COMPASS_TEXT[2], 1.0);
}
/// What does a press at (mx,my) (window px) hit on the compass? 0..5 = axis*2 (+1 for
/// the negative end); 6 = the ball body (furniture — consume the press, no snap);
/// -1 = not on the compass at all. Where dots overlap the closer dot wins, front
/// (toward-viewer) end breaking ties.
pub fn meshCompassHit(mx: f32, my: f32) i32 {
    if (!z3d.g_me_capture or !model_paint.hasTarget()) return -1;
    if (z3d.g_paint_vp_w <= 1 or z3d.g_paint_vp_h <= 1 or !z3d.compassVisible()) return -1;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const g = z3d.compassGeom(cam);
    const dxc = mx - g.cx;
    const dyc = my - g.cy;
    if (dxc * dxc + dyc * dyc > z3d.COMPASS_R_PX * z3d.COMPASS_R_PX) return -1;
    var best: i32 = 6;
    var best_key: f32 = std.math.floatMax(f32);
    for (g.ends, 0..) |e, k| {
        const dx = mx - e.x;
        const dy = my - e.y;
        const d2 = dx * dx + dy * dy;
        if (d2 > z3d.COMPASS_HIT_PX * z3d.COMPASS_HIT_PX) continue;
        const key = d2 + e.depth; // depth ∈ [-1,1] px² — a pure tie-break
        if (key < best_key) {
            best_key = key;
            best = @intCast(k);
        }
    }
    return best;
}
/// Snap the orbit to the axis-aligned view for a compass hit code (axis*2 + neg):
/// clicking a dot moves the EYE onto that world axis (front/right/top…), keeping the
/// target and distance. Y uses the orbit's own pitch clamp — the pole is degenerate
/// for a Y-up camera — so "top" is the same near-vertical view dragging reaches.
pub fn meshCompassSnap(code: i32) bool {
    if (z3d.g_orbit.locked) return false;
    if (code < 0 or code > 5) return false;
    const neg = @rem(code, 2) == 1;
    const half_pi: f32 = std.math.pi / 2.0;
    switch (@divTrunc(code, 2)) {
        0 => { // ±X
            z3d.g_orbit.yaw = if (neg) -half_pi else half_pi;
            z3d.g_orbit.pitch = 0;
        },
        1 => z3d.g_orbit.pitch = if (neg) -z3d.ORBIT_PITCH_LIM else z3d.ORBIT_PITCH_LIM, // ±Y (top/bottom)
        else => { // ±Z
            z3d.g_orbit.yaw = if (neg) std.math.pi else 0;
            z3d.g_orbit.pitch = 0;
        },
    }
    return true;
}

pub fn drawHistoricalPreviewSelection(cam: model_paint.Camera, ox: f32, oy: f32) void {
    const specimen = if (z3d.g_historical_preview.active) |*value| value else return;
    for (specimen.selected_triangles, 0..) |selected, triangle| {
        if (!selected) continue;
        var points: [3][2]f32 = undefined;
        var valid = true;
        for (0..3) |corner| {
            const base = triangle * 24 + corner * 8;
            points[corner] = z3d.ovProject(cam, .{
                specimen.document.verts[base + 0],
                specimen.document.verts[base + 1],
                specimen.document.verts[base + 2],
            }, ox, oy) orelse {
                valid = false;
                break;
            };
        }
        if (!valid) continue;
        inline for (0..3) |edge| {
            const next = (edge + 1) % 3;
            z3d.overlayLine(
                points[edge][0],
                points[edge][1],
                points[next][0],
                points[next][1],
                0.18,
                0.86,
                0.95,
                3.0,
            );
        }
    }
}

/// Draw the editor overlay — the modeling stage (tile panels + grid + axes), mode
/// dressing (face wash/centroid dots, edge lines, vertex dots), loop-cut accents, the
/// gizmo, and the marquee — as screen-space capsules/polys projected with the EXACT
/// last-drawn camera, so every mark sits on the pixel its raycast shoots back through.
/// Capsules/polys ride the 2D draw-command z-order, so emitting right after the Scene3D
/// composite lands them on top; scissor-segment breaks order the fill layers under the
/// line layers. (ox,oy) is the viewport origin (0,0 full-window). Lives here, not in
/// mesh_edit, to keep that GPU-free.
pub fn drawEditorOverlay(ox: f32, oy: f32) void {
    if (!z3d.g_me_capture) return;
    if (!model_paint.hasTarget() or z3d.g_paint_vp_w <= 1 or z3d.g_paint_vp_h <= 1) {
        z3d.drawMarqueeOverlay();
        return;
    }
    // Only the pane that HOLDS the edit target gets the furniture: the engine calls this
    // for every large Scene3D pane, and projecting the target camera through another
    // pane's origin would smear the stage/dots across it.
    if (@abs(ox - z3d.g_paint_vp_x) > 0.5 or @abs(oy - z3d.g_paint_vp_y) > 0.5) return;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    if (z3d.g_historical_preview.active != null) {
        core.pushScissor(ox, oy, z3d.g_paint_vp_w, z3d.g_paint_vp_h);
        z3d.drawHistoricalPreviewSelection(cam, ox, oy);
        core.popScissor();
        return;
    }
    // Paint session (req_2662): the whole mode dressing goes quiet — the stage,
    // compass and marquee are view furniture and stay; wash/dots/edges/gizmo are
    // EDIT affordances and must never render over a paint surface.
    const mode: u8 = if (z3d.g_paint_session) 0 else z3d.meshEditModeRaw();
    // One visibility refresh feeds every edit-mode overlay below: the vertex/edge
    // camera masks AND the Surface-mode occlusion grid the face wash and face dots
    // consult — so it must run before the face-tint layer, not just the edge layer
    // (req_3856).
    const vis_ready = (mode == 1 or mode == 2 or mode == 3) and mesh_edit.refreshCameraVisibility(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h);
    // Clip everything to the pane, and use segment breaks to layer polys under capsules.
    core.pushScissor(ox, oy, z3d.g_paint_vp_w, z3d.g_paint_vp_h);
    if (z3d.g_character_rig.active) {
        z3d.drawStagePanels(cam, ox, oy);
        z3d.overlayLayerBreak(ox, oy);
        z3d.drawStageLines(cam, ox, oy);
        z3d.overlayLayerBreak(ox, oy);
        z3d.drawCharacterRigOverlay(cam, ox, oy);
        if (z3d.g_stage_overlay_options.measurements) z3d.drawStageMeasurements(cam, ox, oy) else z3d.g_stage_measurement_frame = null;
        if (z3d.g_stage_overlay_options.player_scale) z3d.drawStageScaleCue(cam, ox, oy);
        if (z3d.g_stage_overlay_options.measurements or z3d.g_stage_overlay_options.player_scale) {
            z3d.overlayLayerBreak(ox, oy);
            if (z3d.g_stage_overlay_options.measurements) z3d.drawStageMeasurementText(cam, ox, oy);
            if (z3d.g_stage_overlay_options.player_scale) z3d.drawStageScaleText(cam, ox, oy);
        }
        if (z3d.compassVisible()) {
            z3d.overlayLayerBreak(ox, oy);
            z3d.drawCompassBall(cam);
            z3d.overlayLayerBreak(ox, oy);
            z3d.drawCompassText(cam);
        }
        core.popScissor();
        return;
    }
    // Layer 1 (polys): the tile-panel fills. Always drawn in the model doc view — the
    // stage is the scale reference, selection or not (req_2618 A / req_2623).
    z3d.drawStagePanels(cam, ox, oy);
    z3d.overlayLayerBreak(ox, oy);
    // Layer 2 (capsules): tile grid + fine center sub-grid + world axes.
    z3d.drawStageLines(cam, ox, oy);
    z3d.overlayLayerBreak(ox, oy);
    // Layer 3 (polys): an explicit whole-mesh retopo plan wins over ordinary
    // selection wash, including when every face is selected for review.
    const source_ghost_visible = if (z3d.g_retopo_source_ghost) |*ghost| ghost.visible else false;
    if (!z3d.g_paint_session and source_ghost_visible) {
        // Ghost review replaces the moving tint wash: the ordinary current mesh
        // remains underneath while only the frozen before-image is colored.
        z3d.drawRetopoSourceGhost(cam, ox, oy);
    } else if (!z3d.g_paint_session and (z3d.g_retopo_band_plan != null or z3d.g_retopo_manual_bands != null)) {
        z3d.drawRetopoBandOverlay(cam, ox, oy);
    } else if (mode == 3) {
        z3d.drawFaceTintOverlay(cam, ox, oy);
    }
    z3d.overlayLayerBreak(ox, oy);
    // Layer 4 (capsules): edges, dots, loop-cut accents, gizmo, marquee.
    if (vis_ready) {
        z3d.drawEdgeOverlay(cam, mode, ox, oy);
    } else if (mode == 0 and !z3d.g_paint_session and mesh_edit.ensureTopologyPub()) {
        // Plain view: only the naked Pen Edges wires — they have no faces to rasterize,
        // so this is their ONLY visual outside the edit modes. Paint stays quiet (req_2662).
        z3d.drawWireEdgesOverlay(cam, ox, oy);
    }
    if (mode == 3) {
        z3d.drawFaceDotsOverlay(cam, ox, oy);
        z3d.drawFaceCornerIdentityOverlay(cam, ox, oy);
    }
    if (mode == 1) { // vertex: every vert as a haloed dot, selected ones orange + bigger
        const n = mesh_edit.vertCount();
        const draw_all = n <= z3d.OV_MAX_VERT_DOTS;
        // Depth axis for the dot colours: the camera forward SNAPPED to its dominant
        // WORLD axis, anchored at the world origin. Raw view depth spread a genuinely
        // flat plane into two hues whenever the view sat a few degrees off axis — and
        // the compass TOP view deliberately stops at the pitch clamp (~86°, the Y-up
        // pole is degenerate), so even dial-snapped views hit it (req_3066). Snapped,
        // "same depth" means "same world coordinate": exact from any near-axis view,
        // and the palette never swims with the camera at all.
        const fwd = z3d.vnorm(z3d.vsub(cam.target, cam.eye));
        const dax: usize = if (@abs(fwd[0]) >= @abs(fwd[1]) and @abs(fwd[0]) >= @abs(fwd[2])) 0 else if (@abs(fwd[1]) >= @abs(fwd[2])) 1 else 2;
        const dsign: f32 = if (fwd[dax] < 0) -1 else 1; // keep near/far sense with the view
        var i: u32 = 0;
        while (i < n) : (i += 1) {
            if (!mesh_edit.vertInScopePub(i)) continue; // only the focused part's verts
            const selected = mesh_edit.vertSelectedPub(i);
            if (!selected and !mesh_edit.vertexCameraVisiblePub(i)) continue;
            if (!selected and !draw_all) continue;
            const p = mesh_edit.vertPosPub(i);
            const sp = z3d.ovProject(cam, p, ox, oy) orelse continue;
            if (selected) {
                z3d.overlayDot(sp[0], sp[1], z3d.OV_ORANGE[0], z3d.OV_ORANGE[1], z3d.OV_ORANGE[2], 13);
            } else {
                const c = z3d.ovDepthColor(p[dax] * dsign);
                z3d.overlayDot(sp[0], sp[1], c[0], c[1], c[2], 8);
            }
        }
    }
    z3d.drawLoopCutOverlay(cam, ox, oy);
    if (mode != 0) z3d.drawMirrorPlanesOverlay(cam, ox, oy); // req_2758: edit dressing, quiet in paint/view
    z3d.drawGizmoOverlay(cam, ox, oy);
    // Backdrop move session (req_3080): the reference image's own move gizmo — drawn in
    // ANY mode (tracing setup isn't an edit mode), quiet only while paint owns the surface.
    z3d.drawBdGizmoOverlay(cam, ox, oy);
    // Scale and size references are deliberate view tools, never persistent stage
    // furniture. Both default off; each can be enabled independently from Studio View.
    if (z3d.g_stage_overlay_options.measurements) z3d.drawStageMeasurements(cam, ox, oy) else z3d.g_stage_measurement_frame = null;
    if (z3d.g_stage_overlay_options.player_scale) z3d.drawStageScaleCue(cam, ox, oy);
    z3d.drawMarqueeOverlay();
    // Text needs a later segment than measurement/ruler capsules; otherwise the batch's
    // glyph flush lands under them and the numerical marks become unreadable.
    if (z3d.g_stage_overlay_options.measurements or z3d.g_stage_overlay_options.player_scale) {
        z3d.overlayLayerBreak(ox, oy);
        if (z3d.g_stage_overlay_options.measurements) z3d.drawStageMeasurementText(cam, ox, oy);
        if (z3d.g_stage_overlay_options.player_scale) z3d.drawStageScaleText(cam, ox, oy);
    }
    // Layer 5: the orientation compass — always-on view furniture like the stage
    // (req_2643 gap LL). Ball/arms/dots ride this capsule segment (on top of the mesh
    // dressing); the break puts labels + the angle readout in a LATER segment so the
    // glyphs land ON the dots (within one segment text flushes before capsules).
    if (z3d.compassVisible()) {
        z3d.overlayLayerBreak(ox, oy);
        z3d.drawCompassBall(cam);
        z3d.overlayLayerBreak(ox, oy);
        z3d.drawCompassText(cam);
    }
    core.popScissor();
}
